return ['domain'=>'bulk-editor','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'nl_NL','project-id-version'=>'WOLF - WordPress Posts Bulk Editor and Manager Professional 2.1.3','pot-creation-date'=>'2026-11-20T14:15:27+00:00','po-revision-date'=>'2026-11-20 15:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['WOLF - WordPress Posts Bulk Editor and Manager Professional'=>'WOLF - WordPress Posts Bulk Editor and Manager Professional','https://bulk-editor.pro/'=>'https://bulk-editor.pro/','Tools for managing and bulk edit posts, pages and all custom types data in the reliable and flexible way! Be professionals with managing data of your site!'=>'Tools om berichten, pagina’s en gegevens van alle custom types betrouwbaar en flexibel te beheren en in bulk te bewerken. Beheer de gegevens van je site als een professional!','realmag777'=>'realmag777','https://pluginus.net/'=>'https://pluginus.net/','no rounding'=>'geen afronding','forbidden'=>'verboden','Default'=>'Standaard','Checkboxes for the posts selection. Use SHIFT button on your keyboard to select multiple rows.'=>'Selectievakjes voor de berichtselectie. Gebruik de SHIFT-toets op je toetsenbord om meerdere rijen te selecteren.','Thumbnail'=>'Miniatuur','Title'=>'Titel','Content'=>'Inhoud','Excerpt'=>'Samenvatting','Slug'=>'Slug','Status'=>'Status','Comment status'=>'Reactiestatus','Can users comment post or not.'=>'Of gebruikers op het bericht kunnen reageren.','Open'=>'Open','Closed'=>'Gesloten','Ping status'=>'Pingstatus','A ping is a [this site has new content] notification that invites search engine bots to visit your blog.'=>'Een ping is een melding [deze site heeft nieuwe inhoud] die zoekmachinebots uitnodigt je blog te bezoeken.','Send trackbacks to'=>'Trackbacks sturen naar','Separate multiple URLs with spaces. Ping status should be open! Remove 2 links separated by space, save. After opening you will not see links as they had been pinged! No sense for roll back, its sending is instant. Trackbacks are a way to notify legacy blog systems that you’ve linked to them. If you link other WordPress sites, they’ll be notified automatically using pingbacks, no other action necessary. Do not use these fields for something else. They are parsed many times in core code (69 matches for to_ping); their format is fixed.'=>'Scheid meerdere URL’s met spaties. De pingstatus moet open zijn! Verwijder 2 links gescheiden door een spatie en sla op. Na het openen zie je de links niet meer, omdat ze al zijn gepingd! Terugdraaien heeft geen zin, het verzenden is direct. Trackbacks zijn een manier om oudere blogsystemen te laten weten dat je naar ze hebt gelinkt. Als je naar andere WordPress-sites linkt, krijgen die automatisch een melding via pingbacks, verdere actie is niet nodig. Gebruik deze velden niet voor iets anders. Ze worden vaak gebruikt in de kerncode (69 treffers voor to_ping); hun formaat ligt vast.','Post password'=>'Berichtwachtwoord','Password for private posts'=>'Wachtwoord voor privéberichten','Menu order'=>'Menuvolgorde','Custom ordering position.'=>'Eigen sorteerpositie.','Author'=>'Auteur','Date Published'=>'Publicatiedatum','Date Published GMT'=>'Publicatiedatum GMT','Date modified'=>'Wijzigingsdatum','Date modified GMT'=>'Wijzigingsdatum GMT','Post parent'=>'Bovenliggend bericht','Post type'=>'Berichttype','Post mime type'=>'MIME-type van bericht','Not in bulk edit as there is no built-uploader here, so no sense change mime type. Filtering only! The function is designed specifically for attached records.'=>'Niet beschikbaar bij bulkbewerking, omdat hier geen uploader is en het wijzigen van het MIME-type dus zinloos is. Alleen filteren! De functie is speciaal bedoeld voor bijgevoegde items.','Sticky'=>'Vastgezet','Stick this post to the front page'=>'Dit bericht vastzetten op de voorpagina','Yes'=>'Ja','No'=>'Nee','Default posts count per page'=>'Standaard aantal berichten per pagina','How many rows shows per page in tab Posts Editor. Max possible value is 100!'=>'Hoeveel rijen er per pagina worden getoond in het tabblad Berichteneditor. Maximale waarde is 100!','Default sort by'=>'Standaard sorteren op','Select column by which posts sorting is going after plugin page loaded'=>'Kies de kolom waarop de berichten worden gesorteerd nadat de pagina van de plugin is geladen','Default sort'=>'Standaard sortering','Select sort direction for Default sort'=>'Kies de sorteerrichting voor Standaard sortering','Show button in admin bar'=>'Knop tonen in de adminbalk','Show Bulk Editor button in admin bar for quick access to the Posts Editor'=>'Toon de knop Bulk Editor in de adminbalk voor snelle toegang tot de Berichteneditor','Show thumbnail preview'=>'Miniatuurvoorbeeld tonen','Show bigger thumbnail preview on mouse over'=>'Toon een groter miniatuurvoorbeeld bij muisaanwijzing','Load beauty switchers'=>'Mooie schakelaars laden','Load beauty switchers instead of checkboxes in the Posts Editor.'=>'Laad mooie schakelaars in plaats van selectievakjes in de Berichteneditor.','Use gutenberg'=>'Gutenberg gebruiken','Allows to edit content with the gutenberg editor if its enabled for the selected post type'=>'Maakt het mogelijk de inhoud te bewerken met de Gutenberg-editor als die is ingeschakeld voor het gekozen berichttype','Add fields to the quick search'=>'Velden toevoegen aan snel zoeken','Adds more fields to quick search fields drop-down on the tools panel. Works only for text fields. Syntax: post_name:Post slug,post_content:Content'=>'Voegt meer velden toe aan de keuzelijst voor snel zoeken in het toolspaneel. Werkt alleen voor tekstvelden. Syntaxis: post_name:Berichtslug,post_content:Inhoud','Override meta checkbox'=>'Meta-selectievakje overschrijven','By default, the checkbox works with 1 and 0. If you need to redefine these values for example to "yes" or "true". Syntax: meta_key1:yes,meta_key2:true'=>'Standaard werkt het selectievakje met 1 en 0. Als je deze waarden wilt wijzigen, bijvoorbeeld naar “yes” of “true”. Syntaxis: meta_key1:yes,meta_key2:true','Bulk Edit'=>'Bulkbewerking','Will be edited next:'=>'Wordt hierna bewerkt:','Sure? Delete [%s]?'=>'Zeker? [%s] verwijderen?','Bulk deleting'=>'Bulk verwijderen','[%s](s) deleted!'=>'[%s] verwijderd!','Bulk editing'=>'Bulk bewerken','[%s](s) edited! Table redrawing ...'=>'[%s] bewerkt! Tabel wordt vernieuwd ...','[%s](s) edited!'=>'[%s] bewerkt!','ATTENTION: Bulk operation is going!'=>'LET OP: er loopt een bulkbewerking!','binded editing'=>'gekoppeld bewerken','In FREE version of the plugin you can change only next fields: %s'=>'In de GRATIS versie van de plugin kun je alleen deze velden wijzigen: %s','In this mode to the all selected [%1$s](s) will be set the value of a [%2$s] field which been edited'=>'In deze modus krijgen alle geselecteerde [%1$s] de waarde van het bewerkte veld [%2$s]','Select post type you want to manage'=>'Kies het berichttype dat je wilt beheren','title'=>'titel','content'=>'inhoud','excerpt'=>'samenvatting','slug'=>'slug','password'=>'wachtwoord','send trackbacks to'=>'trackbacks sturen naar','post status'=>'berichtstatus','post type'=>'berichttype','comment status'=>'reactiestatus','ping status'=>'pingstatus','sticky posts'=>'vastgezette berichten','increase by value'=>'verhogen met waarde','decrease by value'=>'verlagen met waarde','increase by %'=>'verhogen met %','decrease by %'=>'verlagen met %','set new'=>'nieuw instellen','delete'=>'verwijderen','post parent'=>'bovenliggend bericht','menu order'=>'menuvolgorde','Bulk editing will be applied to: %s'=>'De bulkbewerking wordt toegepast op: %s','all the [%s] on the site'=>'alle [%s] op de site','text'=>'tekst','numeric'=>'numeriek','statuses and types'=>'statussen en types','Do Bulk Edit'=>'Bulkbewerking uitvoeren','terminate bulk operation'=>'bulkbewerking stoppen','Delete [%s]!'=>'[%s] verwijderen!','Notes'=>'Opmerkingen','In red containers wrapped fields which are not possible modify in bulk in FREE version of the plugin!'=>'Velden in rode vakken kunnen in de GRATIS versie van de plugin niet in bulk worden gewijzigd!','In the case of an aborted bulk-operation you can roll back changes in the tab History'=>'Bij een afgebroken bulkbewerking kun je de wijzigingen terugdraaien in het tabblad Geschiedenis','Time by time (one time per week for example) - make the backup of your site database. For example by %s'=>'Maak af en toe (bijvoorbeeld één keer per week) een back-up van de database van je site. Bijvoorbeeld met %s','this plugin'=>'deze plugin','Documentation'=>'Documentatie','select it to use'=>'selecteer om te gebruiken','variable'=>'variabele','TITLE'=>'TITEL','MENU ORDER'=>'MENUVOLGORDE','append'=>'toevoegen aan einde','prepend'=>'toevoegen aan begin','new'=>'nieuw','replace'=>'vervangen','same case'=>'hoofdlettergevoelig','ignore case'=>'hoofdletters negeren','replace to text'=>'vervangen door tekst','Select how to round float values fractions in the numeric fields. Works for numeric meta fields. Read more %s.'=>'Kies hoe de decimalen van kommagetallen in numerieke velden worden afgerond. Werkt voor numerieke metavelden. Lees meer %s.','here'=>'hier','Selected num fields'=>'Gekozen numerieke velden','You can select numeric field then make math operation with another numeric field using [+ - * /] value'=>'Je kunt een numeriek veld kiezen en daarmee een berekening uitvoeren met een ander numeriek veld via [+ - * /] waarde','Random number'=>'Willekeurig getal','Decimal'=>'Decimaal','From:'=>'Van:','To:'=>'Tot:','You can create random numbers for test filling fields or for SEO tasks'=>'Je kunt willekeurige getallen maken om velden te testen of voor SEO-taken','taxonomies'=>'taxonomieën','remove'=>'verwijderen','Set: %s'=>'Instellen: %s','other'=>'overig','select thumbnail'=>'miniatuur kiezen','enter operation value'=>'voer de bewerkingswaarde in','Export'=>'Exporteren','Should the export be started?'=>'Moet de export worden gestart?','Exporting'=>'Exporteren','Exported'=>'Geëxporteerd','ATTENTION: Export operation is going!'=>'LET OP: er loopt een export!','Export will be applied to: %s'=>'De export wordt toegepast op: %s','Note: you can change columns set and then set their order in the tab Settings, then save it as columns profile which in future will help you with exporting the [%s] data format quickly without necessary each time set columns order and their set!'=>'Let op: je kunt de kolommen wijzigen, hun volgorde instellen in het tabblad Instellingen en dit opslaan als kolomprofiel. Zo kun je de gegevens van [%s] later snel exporteren zonder telkens de kolommen en hun volgorde opnieuw in te stellen!','Export to CSV'=>'Exporteren naar CSV','Export to XML'=>'Exporteren naar XML','Export to Excel'=>'Exporteren naar Excel','download'=>'downloaden','download XML'=>'XML downloaden','cancel export'=>'export annuleren','Current export functionality is just for simple operations and data share, if you need something complex find and use especial plugin for Export WordPress data!'=>'De huidige exportfunctie is alleen bedoeld voor eenvoudige bewerkingen en het delen van gegevens. Heb je iets complexs nodig, zoek dan een speciale plugin voor het exporteren van WordPress-gegevens!','Select CSV data delimiter.'=>'Kies het scheidingsteken voor CSV-gegevens.','Filters'=>'Filters','Filtering'=>'Filteren','Filtered! Table redrawing ...'=>'Gefilterd! Tabel wordt vernieuwd ...','LIKE'=>'BEVAT','EXACT'=>'EXACT','NOT'=>'NIET','BEGIN'=>'BEGINT MET','END'=>'EINDIGT MET','ID'=>'ID','quick search by ...'=>'snel zoeken op ...','Filter'=>'Filteren','Reset'=>'Resetten','Empty'=>'Leeg','ID(s). Use comma or/and minus for range'=>'ID’s. Gebruik komma’s en/of een min-teken voor een bereik','[%s] title ...'=>'[%s] titel ...','[%s] content ...'=>'[%s] inhoud ...','[%s] excerpt ...'=>'[%s] samenvatting ...','[%s] slug ...'=>'[%s] slug ...','[%s] password ...'=>'[%s] wachtwoord ...','Menu order from'=>'Menuvolgorde van','Menu order to'=>'Menuvolgorde tot','Post parent from'=>'Bovenliggend bericht van','Post parent to'=>'Bovenliggend bericht tot','[%s] status'=>'[%s] status','Sticky posts'=>'Vastgezette berichten','By author'=>'Op auteur','Not empty'=>'Niet leeg','%s from'=>'%s van','%s to'=>'%s tot','test'=>'test','Filters profiles'=>'Filterprofielen','Profiles'=>'Profielen','Here you can load previously saved filters profile. After pressing on the load button, Posts Editor data reloading will start immediately!'=>'Hier kun je eerder opgeslagen filterprofielen laden. Na het klikken op de laadknop worden de gegevens van de Berichteneditor meteen opnieuw geladen!','Select filter profile to load'=>'Kies een filterprofiel om te laden','load'=>'laden','New Filter Profile'=>'Nieuw filterprofiel','Here you can type any title and save current filters set. Type here any title and then press Save button OR press Enter button on your keyboard!'=>'Voer hier een titel in om de huidige filters op te slaan. Typ een titel en klik op Opslaan OF druk op Enter op je toetsenbord!','You can save filter profile only when you applying filters to the posts.'=>'Je kunt een filterprofiel alleen opslaan wanneer je filters op de berichten toepast.','Save'=>'Opslaan','Close'=>'Sluiten','History'=>'Geschiedenis','Reverting'=>'Terugdraaien','Reverted!'=>'Teruggedraaid!','Wait please while data reverting is going!'=>'Even geduld, de gegevens worden teruggedraaid!','History clearing ...'=>'Geschiedenis wordt gewist ...','History is cleared!'=>'Geschiedenis is gewist!','ATTENTION: History operation is going!'=>'LET OP: er loopt een geschiedenisbewerking!','This clears the history of all users for this post type, including the AI agent rows. It cannot be undone. Continue?'=>'Dit wist de geschiedenis van alle gebruikers voor dit berichttype, inclusief de regels van de AI-agent. Dit kan niet ongedaan worden gemaakt. Doorgaan?','This clears your own history for this post type. It cannot be undone. Continue?'=>'Dit wist je eigen geschiedenis voor dit berichttype. Dit kan niet ongedaan worden gemaakt. Doorgaan?','WOLF cannot create the database table! Make sure that your mysql user has the CREATE privilege! Do it manually using your host panel phpmyadmin!'=>'WOLF kan de databasetabel niet aanmaken! Zorg dat je MySQL-gebruiker het CREATE-recht heeft! Doe het handmatig via het hostingpaneel met phpMyAdmin!','AI agent'=>'AI-agent','user #%d'=>'gebruiker #%d','%s (AI agent)'=>'%s (AI-agent)','This history entry is not yours. Only an administrator can roll back or delete the changes of other users.'=>'Deze geschiedenisregel is niet van jou. Alleen een beheerder kan wijzigingen van andere gebruikers terugdraaien of verwijderen.','Bulk operation'=>'Bulkbewerking','state: %s'=>'status: %s','value been: %s'=>'waarde was: %s','posts bulked: %s'=>'berichten bewerkt: %s','columns: %s'=>'kolommen: %s','revert'=>'terugdraaien','History is empty!'=>'Geschiedenis is leeg!','Works for edit-operations and not work with delete-operations!'=>'Werkt voor bewerkingen en niet voor verwijderacties!','In FREE version of the plugin it is possible to roll back 2 last operations.'=>'In de GRATIS versie van de plugin kun je de laatste 2 bewerkingen terugdraaien.','Per page:'=>'Per pagina:','ALL'=>'ALLES','Clear the History'=>'Geschiedenis wissen','all'=>'alles','solo operations'=>'enkele bewerkingen','bulk operations'=>'bulkbewerkingen','by Author'=>'op auteur','by date from'=>'op datum vanaf','clear'=>'wissen','by date to'=>'op datum tot','by fields'=>'op velden','Prev'=>'Vorige','of'=>'van','Next'=>'Volgende','Help'=>'Hulp','The plugin has next info: %1$s, %2$s, %3$s. Also if you have troubles you can %4$s!'=>'De plugin heeft deze info: %1$s, %2$s, %3$s. Heb je problemen, dan kun je ook %4$s!','documentation'=>'documentatie','translations'=>'vertalingen','FAQ'=>'FAQ','ask for support here'=>'hier om ondersteuning vragen','Current version of the plugin is FREE. See the difference between FREE and PREMIUM versions %s'=>'De huidige versie van de plugin is GRATIS. Bekijk het verschil tussen de GRATIS en PREMIUM versie %s','Some little hints'=>'Handige tips','Can I connect an AI assistant (Claude, ChatGPT, Cursor and others) to WOLF and edit posts by chatting with it? Yes - %s'=>'Kan ik een AI-assistent (Claude, ChatGPT, Cursor en andere) met WOLF verbinden en berichten bewerken door ermee te chatten? Ja - %s','here is how to connect it'=>'zo verbind je hem','If to click on an empty space of the black wp-admin bar, it will get you back to the top of the page'=>'Als je op een lege plek in de zwarte wp-adminbalk klikt, ga je terug naar de bovenkant van de pagina','How to set the same value for some posts on the same time - %s'=>'Zo stel je dezelfde waarde in voor meerdere berichten tegelijk - %s','How to use - %s'=>'Zo gebruik je het - %s','meta field Gallery'=>'metaveld Galerij','Search by posts slugs, which are in non-latin symbols does not work because in the data base they are keeps in the encoded format!'=>'Zoeken op berichtslugs met niet-Latijnse tekens werkt niet, omdat die in de database in gecodeerd formaat staan!','Click ID of the post in the Posts Editor to see it on the site front.'=>'Klik op de ID van het bericht in de Berichteneditor om het op de voorkant van de site te bekijken.','Use Enter keyboard button in the Posts Editor for moving to the next posts row cell with saving of changes while edit textinputs. Use arrow Up or arrow Down keyboard buttons in the Posts Editor for moving to the next/previous posts row without saving of changes.'=>'Gebruik de Enter-toets in de Berichteneditor om tijdens het bewerken van tekstvelden naar de volgende cel in de rij te gaan en de wijzigingen op te slaan. Gebruik de pijltoetsen omhoog en omlaag in de Berichteneditor om naar de volgende/vorige rij te gaan zonder de wijzigingen op te slaan.','To select range of posts using checkboxes - select first post, press SHIFT key on your PC keyboard and click last post.'=>'Een reeks berichten selecteren met de selectievakjes: selecteer het eerste bericht, houd SHIFT op je toetsenbord ingedrukt en klik op het laatste bericht.','If you like WOLF %s about what you liked and what you want to see in future versions of the plugin'=>'Bevalt WOLF je? %s wat je goed vindt en wat je in toekomstige versies van de plugin wilt zien','write us feedback please'=>'laat ons dan feedback achter','If you have an idea you can %s'=>'Heb je een idee? Je kunt het %s','share it with us here'=>'hier met ons delen','Requirements'=>'Vereisten','Recommended min RAM'=>'Aanbevolen minimaal RAM','Minimal PHP version is'=>'Minimale PHP-versie is','Recommended PHP version'=>'Aanbevolen PHP-versie','Type part of a name, login or e-mail'=>'Typ een deel van een naam, login of e-mailadres','No matching user who can work with WOLF'=>'Geen passende gebruiker die met WOLF kan werken','Working...'=>'Bezig...','Disconnect'=>'Verbinding verbreken','Issue a new key? The old key stops working at once and the assistant using it is disconnected.'=>'Een nieuwe sleutel aanmaken? De oude sleutel werkt meteen niet meer en de assistent die hem gebruikt wordt losgekoppeld.','Something went wrong. Reload the page and try again.'=>'Er ging iets mis. Laad de pagina opnieuw en probeer het nog eens.','cannot connect: this user can no longer work with WOLF'=>'verbinden niet mogelijk: deze gebruiker kan niet meer met WOLF werken','no key yet - it is issued when the user opens his settings'=>'nog geen sleutel - die wordt aangemaakt wanneer de gebruiker zijn instellingen opent','MCP access for users'=>'MCP-toegang voor gebruikers','Save the settings after changing the list. A user taken off the list loses his key and his connection at once.'=>'Sla de instellingen op nadat je de lijst hebt gewijzigd. Een gebruiker die van de lijst wordt gehaald, verliest meteen zijn sleutel en verbinding.','Users picked here get a personal MCP key in their own settings and connect an AI assistant under their own WordPress account: the assistant can do exactly what they can do by hand, with their role and field visibility, never more. Two-factor connection is always on for personal keys. Only users who can work with WOLF are offered. The site-wide key above is not affected and stays yours.'=>'Hier gekozen gebruikers krijgen in hun eigen instellingen een persoonlijke MCP-sleutel en verbinden een AI-assistent onder hun eigen WordPress-account: de assistent kan precies doen wat zij zelf met de hand kunnen doen, met hun rol en veldzichtbaarheid, nooit meer. Tweefactorverbinding staat bij persoonlijke sleutels altijd aan. Alleen gebruikers die met WOLF kunnen werken worden aangeboden. De sleutel voor de hele site hierboven blijft ongewijzigd van jou.','Your MCP access'=>'Jouw MCP-toegang','Address for the assistant:'=>'Adres voor de assistent:','Your personal key:'=>'Je persoonlijke sleutel:','Regenerate key'=>'Sleutel opnieuw aanmaken','Give the assistant the address and this key as a request header: Authorization, with the value "Bearer" followed by a space and the key. Two-factor connection is always on for a personal key: every session starts with a token the assistant shows you, which you confirm below.'=>'Geef de assistent het adres en deze sleutel als request-header: Authorization, met de waarde “Bearer”, een spatie en de sleutel. Tweefactorverbinding staat bij een persoonlijke sleutel altijd aan: elke sessie begint met een token dat de assistent je toont en dat je hieronder bevestigt.','Confirm assistant connection - paste the token the assistant gave you:'=>'Bevestig de verbinding met de assistent - plak het token dat de assistent je gaf:','Confirm connection'=>'Verbinding bevestigen','The administrator gave you MCP access. An assistant connected with your key works as you: it can do what you can do by hand in this plugin, with your role and field visibility. Keep the key private; if it may have leaked, press Regenerate key - the old key and its connection stop working at once.'=>'De beheerder heeft je MCP-toegang gegeven. Een assistent die met jouw sleutel is verbonden, werkt als jij: hij kan doen wat jij met de hand in deze plugin kunt doen, met jouw rol en veldzichtbaarheid. Houd de sleutel privé; als hij gelekt kan zijn, klik dan op Sleutel opnieuw aanmaken - de oude sleutel en de verbinding werken dan meteen niet meer.','You cannot work with WOLF on this site.'=>'Je kunt op deze site niet met WOLF werken.','Only an administrator can do this.'=>'Alleen een beheerder kan dit doen.','You have no MCP access on this site. Ask the administrator to grant it.'=>'Je hebt geen MCP-toegang op deze site. Vraag de beheerder om die te geven.','No user given.'=>'Geen gebruiker opgegeven.','Disconnected.'=>'Verbinding verbroken.','A new key is issued. The old one no longer works - update it in your assistant.'=>'Er is een nieuwe sleutel aangemaakt. De oude werkt niet meer - werk hem bij in je assistent.','That is not a connection token. Copy the whole token the assistant gave you - four groups of eight characters separated by dashes.'=>'Dat is geen verbindingstoken. Kopieer het hele token dat de assistent je gaf - vier groepen van acht tekens gescheiden door streepjes.','Connected. Go back to the assistant and tell it you have confirmed.'=>'Verbonden. Ga terug naar de assistent en laat weten dat je het hebt bevestigd.','Not connected'=>'Niet verbonden','Connected, last activity %d min ago'=>'Verbonden, laatste activiteit %d min geleden','Only an administrator can confirm a connection.'=>'Alleen een beheerder kan een verbinding bevestigen.','Only an administrator can end a connection.'=>'Alleen een beheerder kan een verbinding beëindigen.','No assistant is connected.'=>'Er is geen assistent verbonden.','An assistant is connected since %1$s. If it stays idle, the connection ends at %2$s.'=>'Een assistent is verbonden sinds %1$s. Als hij inactief blijft, eindigt de verbinding om %2$s.','Recommended: turn on two-factor connection. Without it, anyone who gets hold of the MCP key - from a screenshot, a shared config or a stolen laptop - can work with your site. With it, every assistant session also needs a token that you confirm here yourself, and that expires after %s without use.'=>'Aanbevolen: schakel tweefactorverbinding in. Zonder dit kan iedereen die de MCP-sleutel in handen krijgt - via een screenshot, een gedeelde configuratie of een gestolen laptop - met je site werken. Mét tweefactorverbinding heeft elke assistentsessie ook een token nodig dat je hier zelf bevestigt en dat na %s zonder gebruik verloopt.','Enable the MCP server'=>'MCP-server inschakelen','The MCP server is on: assistants can connect at the address below.'=>'De MCP-server staat aan: assistenten kunnen verbinden op het onderstaande adres.','The MCP server is off and no assistant can connect. Choose Yes here: the key and the other MCP settings appear below, and Save switches the server on.'=>'De MCP-server staat uit en geen enkele assistent kan verbinden. Kies hier Ja: de sleutel en de andere MCP-instellingen verschijnen hieronder en Opslaan schakelt de server in.','Off by default. The MCP server lets an AI assistant read and edit the posts of this site over a REST endpoint. While it is off, the endpoint is not registered at all and nothing can reach it. Turn it on only when you are about to connect an assistant, and turn it back off if you stop using one.'=>'Standaard uit. De MCP-server laat een AI-assistent de berichten van deze site lezen en bewerken via een REST-endpoint. Zolang hij uit staat, is het endpoint helemaal niet geregistreerd en kan niets het bereiken. Zet hem pas aan wanneer je een assistent gaat verbinden, en zet hem weer uit als je er geen meer gebruikt.','MCP secret key'=>'MCP-geheime sleutel','Not active: the MCP server is switched off above.'=>'Niet actief: de MCP-server is hierboven uitgeschakeld.','Adding it in claude.ai: its server check will say "Couldn\'t check the server" with 403. That is expected for a server that signs in with a key - press "Continue anyway" and add the header Authorization with the value "Bearer" followed by a space and the key.'=>'Bij toevoegen in claude.ai: de servercontrole meldt “Couldn\'t check the server” met 403. Dat is normaal voor een server die met een sleutel inlogt - klik op “Continue anyway” en voeg de header Authorization toe met de waarde “Bearer”, een spatie en de sleutel.','How to connect an AI assistant'=>'Een AI-assistent verbinden','Lets an AI assistant work with the posts of this site through a chat: find them, change them in bulk, roll changes back. Give the assistant the address below and this key as a request header named Authorization, with the value "Bearer" followed by a space and the key. Some clients call it an API key header instead - X-WPBE-KEY works the same way. The key is never accepted in the address itself, because anything written into a URL ends up in server logs, browser history and every proxy along the way. Clear this field and press Save to issue a new key: the old one stops working at once and every connected assistant has to be reconnected.'=>'Laat een AI-assistent via een chat met de berichten van deze site werken: ze zoeken, in bulk wijzigen en wijzigingen terugdraaien. Geef de assistent het onderstaande adres en deze sleutel als request-header met de naam Authorization en de waarde “Bearer”, een spatie en de sleutel. Sommige clients noemen dit een API-key-header - X-WPBE-KEY werkt op dezelfde manier. De sleutel wordt nooit in het adres zelf geaccepteerd, omdat alles wat in een URL staat in serverlogs, browsergeschiedenis en elke proxy onderweg terechtkomt. Maak dit veld leeg en klik op Opslaan om een nieuwe sleutel aan te maken: de oude werkt dan meteen niet meer en elke verbonden assistent moet opnieuw worden verbonden.','MCP two-factor connection'=>'MCP-tweefactorverbinding','recommended'=>'aanbevolen','This does not switch the MCP server on - that is "Enable the MCP server" above. Two-factor connection takes effect once the server is on.'=>'Dit schakelt de MCP-server niet in - dat doe je met “MCP-server inschakelen” hierboven. Tweefactorverbinding werkt zodra de server aan staat.','Off by default, recommended. With it on, the MCP key alone is not enough: every assistant session starts by showing you a token, you paste it below and confirm, and only then can the assistant work. The connection ends by itself after %s without activity, so a leaked key is useless without you. One assistant is connected at a time.'=>'Standaard uit, aanbevolen. Als dit aan staat, is de MCP-sleutel alleen niet genoeg: elke assistentsessie begint met een token dat je hieronder plakt en bevestigt, en pas dan kan de assistent aan het werk. De verbinding eindigt vanzelf na %s zonder activiteit, zodat een gelekte sleutel zonder jou nutteloos is. Er is telkens één assistent tegelijk verbonden.','Upload images'=>'Afbeeldingen uploaden','Add images to your site'=>'Afbeeldingen aan je site toevoegen','The first one becomes the featured image of %s.'=>'De eerste wordt de uitgelichte afbeelding van %s.','They go into the media library, ready to put on a post.'=>'Ze komen in de mediabibliotheek, klaar om in een bericht te gebruiken.','Drop images here'=>'Sleep afbeeldingen hierheen','or click to choose them'=>'of klik om ze te kiezen','Meta Fields'=>'Metavelden','Meta key cannot be empty!'=>'Metasleutel mag niet leeg zijn!','Enter a post ID!'=>'Voer een bericht-ID in!','No meta keys found!'=>'Geen metasleutels gevonden!','New meta key'=>'Nieuwe metasleutel','EXACT (=)'=>'EXACT (=)','NOT EXACT (!=)'=>'NIET EXACT (!=)','NOT LIKE'=>'BEVAT NIET','NOT Empty'=>'NIET leeg','In FREE version of the plugin it is possible manipulate with 2 meta fields.'=>'In de GRATIS versie van de plugin kun je met 2 metavelden werken.','Add Custom key by hands'=>'Eigen sleutel handmatig toevoegen','Add'=>'Toevoegen','Get meta keys from any post by its ID'=>'Metasleutels ophalen van een bericht via de ID','enter post ID'=>'voer bericht-ID in','Get'=>'Ophalen','Meta quick search ...'=>'Meta snel zoeken ...','Save meta fields'=>'Metavelden opslaan','move'=>'verplaatsen','enter title'=>'voer titel in','textinput'=>'tekstinvoer','textarea'=>'tekstgebied','checkbox'=>'selectievakje','calendar'=>'kalender','array'=>'array','gallery'=>'galerij','string'=>'string','number'=>'nummer','Hello, looks like you bought and installed premium version of WOLF - WordPress Posts Bulk Editor and Manager Professional, please deactivate free version before, then uninstall it. 2 versions of the same plugin cannot be activated on the same time!'=>'Hallo, het lijkt erop dat je de premiumversie van WOLF - WordPress Posts Bulk Editor and Manager Professional hebt gekocht en geïnstalleerd. Deactiveer eerst de gratis versie en verwijder die daarna. Twee versies van dezelfde plugin kunnen niet tegelijk actief zijn!','If you not familiar with the plugin, firstly'=>'Ken je de plugin nog niet? Ga dan eerst','visit this page'=>'naar deze pagina','please'=>'alsjeblieft','WOLF Bulk Editor'=>'WOLF Bulk Editor','Posts Editor'=>'Berichteneditor','Search'=>'Zoeken','Failed'=>'Mislukt','Error'=>'Fout','ignore'=>'negeren','This is not deletable!'=>'Dit kan niet worden verwijderd!','no items'=>'geen items','none'=>'geen','no data'=>'geen gegevens','Loading'=>'Laden','Loaded'=>'Geladen','Saved'=>'Opgeslagen','Saving'=>'Bezig met opslaan','Apply'=>'Toepassen','Cancel'=>'Annuleren','Canceled'=>'Geannuleerd','Sure?'=>'Zeker?','Creating'=>'Bezig met aanmaken','Created!'=>'Aangemaakt!','Duplicating'=>'Bezig met dupliceren','Duplicated!'=>'Gedupliceerd!','Deleting'=>'Bezig met verwijderen','Deleted!'=>'Verwijderd!','Reseting'=>'Bezig met resetten','Reseted!'=>'Gereset!','Upload image'=>'Afbeelding uploaden','Upload file'=>'Bestand uploaden','Fill up the data please!'=>'Vul de gegevens in!','Enter how many time duplicate selected [%s](s)!'=>'Voer in hoe vaak de geselecteerde [%s] moeten worden gedupliceerd!','Enter how many new [%s](s) to create!'=>'Voer in hoeveel nieuwe [%s] er moeten worden aangemaakt!','Text search by title or SKU'=>'Tekst zoeken op titel of SKU','Show: Filters/Bulk Edit/Export'=>'Tonen: Filters/Bulkbewerking/Export','Hide: Filters/Bulk Edit/Export'=>'Verbergen: Filters/Bulkbewerking/Export','Per page'=>'Per pagina','Select background color'=>'Kies achtergrondkleur','Select text color'=>'Kies tekstkleur','No data available in the table'=>'Geen gegevens beschikbaar in de tabel','Showing _START_ to _END_ of _TOTAL_ entries'=>'_START_ tot _END_ van _TOTAL_ items','Showing 0 to 0 of 0 entries'=>'0 tot 0 van 0 items','(filtered from _MAX_ total entries)'=>'(gefilterd uit _MAX_ items in totaal)','Loading...'=>'Laden...','Processing...'=>'Verwerken...','No matching records found'=>'Geen overeenkomende records gevonden','First'=>'Eerste','Last'=>'Laatste','Previous'=>'Vorige','the filtered [%s]. To remove filtering press reset button on the tools panel below'=>'de gefilterde [%s]. Klik op de resetknop in het toolspaneel hieronder om het filteren te verwijderen','the selected [%s](s)'=>'de geselecteerde [%s]','You can reset selection of the [%s](s) by its reset button on the panel of the editor OR uncheck them manually!'=>'Je kunt de selectie van [%s] resetten met de resetknop op het editorpaneel OF ze handmatig deselecteren!','Maybe term(s) with such name(s) already exists!'=>'Misschien bestaat er al een term met deze naam!','In FREE version of the plugin you can create one profile only!'=>'In de GRATIS versie van de plugin kun je maar één profiel aanmaken!','append sub item'=>'subitem toevoegen','This field is deactivated in FREE version for bulk edit!'=>'Dit veld is in de GRATIS versie uitgeschakeld voor bulkbewerking!','Posts checked'=>'Berichten aangevinkt','View the post on the site front'=>'Bekijk het bericht op de voorkant van de site','Editing of the post on its page'=>'Het bericht bewerken op zijn eigen pagina','Posts not found!'=>'Geen berichten gevonden!','New %s'=>'Nieuw: %s','copy'=>'kopie','see the post on the site'=>'bekijk het bericht op de site','Scheduled'=>'Ingepland','Later'=>'Later','Hi! Are you enjoying using WOLF – WordPress Posts Bulk Editor Professional?'=>'Hoi! Werk je met plezier met WOLF – WordPress Posts Bulk Editor Professional?','Yes, I love it'=>'Ja, ik ben er blij mee','Not really...'=>'Niet echt...','That\'s awesome! Could you please do us a BIG favor and give it a 5-star rating on %s to help us spread the word and boost our motivation?'=>'Mooi! Zou je ons een GROTE dienst willen bewijzen en ons een beoordeling van 5 sterren geven op %s, zodat meer mensen ons leren kennen en wij gemotiveerd blijven?','Okay, you deserve it'=>'Prima, dat verdien je','Nope, maybe later'=>'Nee, misschien later','I already did'=>'Heb ik al gedaan','We are sorry to hear you aren\'t enjoying WOLF. We would love a chance to improve it. Could you take a minute and let us know what we can do better?'=>'Jammer dat WOLF je niet bevalt. We willen het graag verbeteren. Wil je even laten weten wat we beter kunnen doen?','Give Feedback'=>'Feedback geven','No thanks'=>'Nee, bedankt','Will never reset published date, and for modified date field  will set current time!'=>'De publicatiedatum wordt nooit gereset en bij het veld Wijzigingsdatum wordt de huidige tijd ingesteld!','Product: %s'=>'Product: %s','Images (%s)'=>'Afbeeldingen (%s)','Post: %s'=>'Bericht: %s','Array'=>'Array','Content[empty]'=>'Inhoud[leeg]','Not allowed!'=>'Niet toegestaan!','Posts (%s)'=>'Berichten (%s)','Select all'=>'Alles selecteren','Deselect all'=>'Alles deselecteren','cancel'=>'annuleren','save'=>'opslaan','Set full width'=>'Volledige breedte instellen','Columns profiles'=>'Kolomprofielen','New Post'=>'Nieuw bericht','Duplicate selected post(s).'=>'Geselecteerde berichten dupliceren.','Delete selected post(s)'=>'Geselecteerde berichten verwijderen','Uncheck all selected posts'=>'Alle geselecteerde berichten deselecteren','Reset filters'=>'Filters resetten','select all variations'=>'alle variaties selecteren','Scroll right'=>'Naar rechts scrollen','Scroll left'=>'Naar links scrollen','Detach image of the post'=>'Afbeelding van het bericht loskoppelen','drag and drop'=>'slepen en neerzetten','Close the panel'=>'Paneel sluiten','No any post type permitted to edit for site editors. Ask please site administrators for details!'=>'Geen enkel berichttype mag door siteredacteuren worden bewerkt. Vraag de sitebeheerders om details!','Your settings have been saved.'=>'Je instellingen zijn opgeslagen.','Compatible with WordPress v.%s'=>'Compatibel met WordPress v.%s','MCP server is off. Connect your AI assistant to WOLF: switch it on in the Settings tab - click to read how'=>'MCP-server staat uit. Verbind je AI-assistent met WOLF: schakel hem in op het tabblad Instellingen - klik om te lezen hoe','MCP server is on, two-factor connection is off - switching it on in the Settings tab is recommended. Click to read how to connect your AI assistant'=>'MCP-server staat aan, tweefactorverbinding staat uit - inschakelen op het tabblad Instellingen wordt aanbevolen. Klik om te lezen hoe je je AI-assistent verbindt','MCP server is on, with two-factor connection. Click to read how to connect your AI assistant'=>'MCP-server staat aan, met tweefactorverbinding. Klik om te lezen hoe je je AI-assistent verbindt','Upgrade'=>'Upgraden','ATTENTION! Your version of the WordPress is obsolete. There is no warranty of normal working with the plugin!!'=>'LET OP! Je versie van WordPress is verouderd. Er is geen garantie dat de plugin normaal werkt!!','Settings'=>'Instellingen','Select some columns in tab "Settings"'=>'Selecteer enkele kolommen op het tabblad “Instellingen”','Actions'=>'Acties','Quick search'=>'Snel zoeken','Quick terms search by its name'=>'Termen snel zoeken op naam','create new term'=>'nieuwe term maken','selected only'=>'alleen geselecteerde','Select all terms'=>'Alle termen selecteren','Add Image'=>'Afbeelding toevoegen','Replace all posts images by the selected ones'=>'Alle afbeeldingen van de berichten vervangen door de geselecteerde','Add selected images to the already existed ones'=>'Geselecteerde afbeeldingen toevoegen aan de bestaande','Delete selected images from the posts'=>'Geselecteerde afbeeldingen uit de berichten verwijderen','Delete selected images from the posts, also delete them from the media library forever'=>'Geselecteerde afbeeldingen uit de berichten verwijderen en ook definitief uit de mediabibliotheek','REMEMBER: sequence of data maybe have sense (and maybe not), so be attentive! Do not mix in the same popup window data of array and object data!'=>'LET OP: de volgorde van de gegevens kan van belang zijn (of niet), dus wees voorzichtig! Meng in hetzelfde popupvenster geen array- en objectgegevens!','Prepend array key/value'=>'Array-sleutel/waarde vooraan toevoegen','Prepend object set'=>'Objectset vooraan toevoegen','Append array key/value'=>'Array-sleutel/waarde achteraan toevoegen','Append object set'=>'Objectset achteraan toevoegen','key'=>'sleutel','value'=>'waarde','Note: if horizontal scroll disappeared when it must be visible, click on tab Posts Editor to make it visible'=>'Let op: als de horizontale scrollbalk verdwenen is terwijl hij zichtbaar moet zijn, klik dan op het tabblad Berichteneditor om hem weer te tonen','Columns settings%1$s, columns enabled %2$s'=>'Kolominstellingen%1$s, kolommen ingeschakeld %2$s','Show all columns'=>'Alle kolommen tonen','premium version'=>'premiumversie','visible for the site editor'=>'zichtbaar voor de siteredacteur','cell text or number size'=>'grootte van celtekst of -getal','Save all settings'=>'Alle instellingen opslaan','General settings'=>'Algemene instellingen','Site editors post types'=>'Berichttypes voor siteredacteuren','What post types can edit site editors in the tab Posts Editor. Use comma, example: post,car,page'=>'Welke berichttypes siteredacteuren kunnen bewerken in het tabblad Berichteneditor. Gebruik komma’s, bijvoorbeeld: post,car,page','Separate columns and meta for post types'=>'Aparte kolommen en meta per berichttype','Each post type has its own set of columns and meta fields.'=>'Elk berichttype heeft zijn eigen set kolommen en metavelden.','Show content and excerpt text partly'=>'Inhoud en samenvatting gedeeltelijk tonen','Show part of the text in the content and excerpt edit button'=>'Toon een deel van de tekst in de bewerkknop van inhoud en samenvatting','More settings (implicit)'=>'Meer instellingen (impliciet)','Show description'=>'Beschrijving tonen','Edit'=>'Bewerken','Columns profile'=>'Kolomprofiel','Here you can load previously saved columns profile. After pressing on the load button, page reloading will start immediately!'=>'Hier kun je een eerder opgeslagen kolomprofiel laden. Na het klikken op de laadknop wordt de pagina meteen opnieuw geladen!','Current profile is: %1$s %2$s'=>'Huidig profiel: %1$s %2$s','remove current columns profile'=>'huidig kolomprofiel verwijderen','Select profile to load'=>'Kies een profiel om te laden','New Profile'=>'Nieuw profiel','Here you can type any title and save current columns set and their order. Type here any title and then press Save button OR press Enter button on your keyboard!'=>'Voer hier een titel in om de huidige kolommen en hun volgorde op te slaan. Typ een titel en klik op Opslaan OF druk op Enter op je toetsenbord!','Create'=>'Aanmaken','New term for [%s]'=>'Nieuwe term voor [%s]','New Term(s)'=>'Nieuwe term(en)','Here you can write title for the new term. Use comma to create some new tags on the same time! New terms with already existed names will not be created!'=>'Hier kun je de titel van de nieuwe term invullen. Gebruik komma’s om meerdere nieuwe tags tegelijk aan te maken! Nieuwe termen met een al bestaande naam worden niet aangemaakt!','Slug(s) of the new term'=>'Slug(s) van de nieuwe term','Here you can write slug for the the new term (optionally). Use comma for slug(s) when you create some on the same time terms, or leave slug field empty to create slug(s) automatically'=>'Hier kun je de slug voor de nieuwe term invullen (optioneel). Gebruik komma’s voor de slugs als je meerdere termen tegelijk aanmaakt, of laat het slugveld leeg om slugs automatisch te laten maken','Parent of the new term(s)'=>'Bovenliggende term van de nieuwe term(en)','Here you can select parent for the the new term (optionally)'=>'Hier kun je de bovenliggende term voor de nieuwe term(en) kiezen (optioneel)','UPGRADE TO FULL VERSION'=>'UPGRADEN NAAR DE VOLLEDIGE VERSIE','WOLF - Posts Bulk Editor Professional'=>'WOLF - Posts Bulk Editor Professional','BEAR - Bulk Editor Professional for WooCommerce'=>'BEAR - Bulk Editor Professional for WooCommerce','BEAR - WooCommerce Bulk Editor Professional'=>'BEAR - WooCommerce Bulk Editor Professional']];